-- Add charity shops as a first-class London Advanced place category.

-- Approved inventory: 29 October 2026; TfL zones 1-4 focus.

INSERT OR IGNORE INTO categories(code,label_en,label_it,display_order) VALUES ('CHARITY_SHOP','Charity shops','Negozi solidali',10);

CREATE TABLE IF NOT EXISTS charity_shop_details (place_id TEXT PRIMARY KEY REFERENCES places(id) ON DELETE CASCADE, organisation_id TEXT NOT NULL, organisation_name TEXT NOT NULL, branch_name TEXT NOT NULL, subtype TEXT NOT NULL, address TEXT NOT NULL, postcode TEXT NOT NULL DEFAULT '', tfl_zone TEXT NOT NULL DEFAULT '', specialism_en TEXT NOT NULL DEFAULT '', specialism_it TEXT NOT NULL DEFAULT '', opening_hours_en TEXT NOT NULL DEFAULT '', opening_hours_it TEXT NOT NULL DEFAULT '', source_url TEXT NOT NULL, data_status TEXT NOT NULL DEFAULT 'verified_inventory', last_verified_at TEXT NOT NULL);

CREATE INDEX IF NOT EXISTS idx_charity_shop_details_org ON charity_shop_details(organisation_id, subtype);

































































































































































































































































































































































































































































































































































































































































































































































UPDATE app_meta SET value=CAST(CAST(value AS INTEGER)+1 AS TEXT),updated_at=CURRENT_TIMESTAMP WHERE key='data_version';
